div.div:
useEffect(() => {
let current = true;
fetch(url).then(r => r.json()).then(d => {
if (current) setResults(d); // last one wins
});
return () => { current = false; };
}, [url]);

useEffect(() => {
const ac = new AbortController();
fetch(url, { signal: ac.signal })
.then(r => r.json())
.then(setResults)
.catch(e => { if (e.name !== "AbortError") throw e; });
return () => ac.abort();
}, [url]);
